using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}
```

### 2. Create `Services/CatalogService.cs` — an in-memory data service:

```csharp
namespace UniversityCourseCatalog.Services;

using UniversityCourseCatalog.Models;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn fundamental programming concepts using C#. Topics include variables, control flow, data structures, and object-oriented programming.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor is a specialist in algorithm design and computational complexity. He previously worked at Google Research before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Title = "Database Systems", Code = "CS 305", Description = "Design and implementation of database management systems. Covers relational models, SQL, normalization, indexing, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez brings 10 years of industry experience in distributed databases. She has contributed to open-source database projects and holds patents in query optimization.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Introduction to differential calculus. Topics include limits, derivatives, applications of differentiation, and an introduction to integration.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years. He is known for making abstract concepts accessible through real-world applications.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Lisa Yamamoto", InstructorBio = "Dr. Yamamoto's research focuses on numerical linear algebra and its applications in machine learning. She received the university's Distinguished Teaching Award in 2024.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, Title = "General Physics I", Code = "PHYS 101", Description = "Introduction to classical mechanics including kinematics, Newton's laws, energy, momentum, rotational motion, and gravitation.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM, Lab: Thu 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter physics. He emphasizes hands-on laboratory experience in his teaching.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 7, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Introduction to quantum theory including wave functions, the Schrödinger equation, quantum states, operators, and applications to atomic systems.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson is a theoretical physicist whose research explores quantum information theory. She has published over 50 papers in leading physics journals.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
